import java.util.*;class TaskBinding{static Object count(String[]codes){return alternate.Audit.count(codes);}static Set<String>unique(Object result){Set<String>out=new HashSet<>();for(alternate.CodeKey key:((alternate.Audit.Result)result).unique())out.add(key.code());return out;}static Map<String,Integer>counts(Object result){Map<String,Integer>out=new HashMap<>();for(var e:((alternate.Audit.Result)result).counts().entrySet())out.put(e.getKey().code(),e.getValue());return out;}static Integer lookup(Object result,String code){return ((alternate.Audit.Result)result).counts().get(new alternate.CodeKey(code));}static boolean equal(String a,String b){return new alternate.CodeKey(a).equals(new alternate.CodeKey(b));}static int hash(String a){return new alternate.CodeKey(a).hashCode();}}
